use vstd::prelude::*;

verus! {
    fn reverse(a: &[i32]) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[(a.len() - 1 - i) as usize],
    {
        let n = a.len() as nat;
        let mut result: Vec<i32> = Vec::new();
        result.reserve(n as usize); // Reserve space for the result vector

        let mut i: nat = 0;
        while i < n
            invariant
                i <= n,
                result.len() == i as usize,
                forall|j: nat| 0 <= j < i ==> result[j] == a[(n - 1 - j) as usize],
            decreases n - i,
        {
            result.push(a[(n - 1 - i) as usize]);
            i = i + 1;
        }
        result
    }
}

